// Build a batch enrichment prompt for Claude
const tasks = $input.first().json.tasks || [];

if (tasks.length === 0) {
  return [{ json: { skipEnrichment: true, message: 'No RAW URL DROPPED tasks to enrich.' } }];
}

const getField = (task, fieldId) => {
  const cf = (task.custom_fields || []).find(f => f.id === fieldId);
  return cf ? (cf.value || null) : null;
};

const items = tasks.slice(0, 25).map((t, i) => ({
  index: i + 1,
  taskId: t.id,
  taskName: t.name,
  url: getField(t, '5afbee8e-16bc-4c70-9acd-7647ffad17e4') || '',
  existingName: getField(t, '39c566b3-6c37-4c7e-999d-800000f902a3') || t.name
}));

const promptItems = items.map(it =>
  `${it.index}. Task ID: ${it.taskId}\n   Name: ${it.existingName}\n   URL: ${it.url}`
).join('\n\n');

const systemPrompt = `You are a wedding registry analyst for Zuha, a Muslim woman in Houston/Dallas area. 
Context:
- Moving in with fiancé soon; first apartment together
- Zuha is a beginner cook learning halal meals; fiancé may have residency match in WV (small town) or stay in Houston/Dallas
- 7-year planning horizon (residency period)
- Apartment living: limited counter space, no drilling
- Dual-career couple; both WFH some days
- Google/Gemini ecosystem

For each numbered product below, return a JSON array where each object has:
{
  "taskId": "<exact task ID>",
  "cleanProductName": "<concise product name, max 80 chars>",
  "retailPrice": <number or null>,
  "guestPriceBracket": "<$50" | "$50\u2013$150" | "$150\u2013$300" | "$300+ (Group Gift)" | null,
  "bestRegistryVendor": "Amazon" | "Crate & Barrel" | "Williams Sonoma" | "Target" | "Best Buy" | "Direct / Universal" | null,
  "registryDecisionVerdict": "Auto-Shortlist (High ROI)" | "Keep If Counter Space Allows" | "Swap for Smarter/BIFL Alternative" | "Reject (Clutter/Failure Risk)" | "Needs Manual Verification",
  "residencyHorizonTier": "7+ Yr Survivor (Attending-Ready)" | "Residency Workhorse (4\u20136 Yrs)" | "3-Yr Disposable Risk" | null,
  "roomZone": "Kitchen & Halal Prep" | "Sleep & Post-Call Recovery" | "Remote Home Office" | "Cleaning & Laundry" | "Bath & Linen" | null,
  "halalFit": "Critical for Small-Town WV Bulk/Freezer" | "High Value in Both TX & WV" | "Optimized for Houston/Dallas Takeout/Fresh" | "Not Applicable" | null,
  "beginnerCooking": "One-Touch / Foolproof" | "Guided App Recipes" | "Moderate Skill" | "High Burn / Timing Skill Risk" | "Non-Kitchen" | null,
  "subscriptionTrap": "Zero Ongoing Fees" | "Optional Cloud Features" | "Mandatory Paywall / Proprietary Cartridges" | null,
  "choiceQuotient": <number 1-10 or null>,
  "familyGiftPitch": "<one-liner pitch for family, max 120 chars or null>"
}
Return ONLY valid JSON array. No markdown, no explanation. Use null for uncertain fields.
For registryDecisionVerdict, use 'Needs Manual Verification' when evidence is thin.`;

return [{
  json: {
    items,
    systemPrompt,
    userPrompt: `Enrich these ${items.length} registry items:\n\n${promptItems}`,
    skipEnrichment: false
  }
}];

// Parse Claude response and map to ClickUp field UUIDs
