};

let enrichedItems;
try {
  enrichedItems = JSON.parse(text);
} catch (e) {
  const match = text.match(/\[.*\]/s);
  if (match) enrichedItems = JSON.parse(match[0]);
  else throw new Error('Claude returned non-JSON: ' + text.substring(0, 200));
}

const AI_ENRICHED_STATUS = 'sc1300320000015716_rkXp4gAL';

return enrichedItems.map(item => {
  const customFields = [];
  for (const [key, fieldId] of Object.entries(FIELDS)) {
    const val = item[key];
    if (val === null || val === undefined) continue;
    if (OPTIONS[key]) {
      const uuid = OPTIONS[key][val];
      if (uuid) customFields.push({ id: fieldId, value: uuid });
    } else {
      customFields.push({ id: fieldId, value: val });
    }
  }
  return {
    json: {
      taskId: item.taskId,
      status: AI_ENRICHED_STATUS,
      customFields
    }
  };
});
